<?php require_once __DIR__.'/includes/functions.php';$items=cart();$product_ids=[];foreach($items as $k=>$it)$product_ids[]=$it['product_id']??(int)$k;$products=get_products($product_ids);$subtotal=0;foreach($items as $k=>$item){$pid=$item['product_id']??(int)$k;if(isset($products[$pid]))$subtotal+=$products[$pid]['price']*$item['qty'];}$title='حقيبتي | ALAN';include __DIR__.'/includes/header.php';?><div class="page"><div class="page-title"><p class="eyebrow">حقيبتي</p><h1>اختياراتكِ الجميلة</h1></div><?php if(!$products):?><div class="empty">حقيبتكِ فارغة الآن.<br><br><a class="btn" href="<?=base('shop.php')?>">ابدئي التسوق</a></div><?php else:?><div class="cart-layout"><div><?php foreach($items as $k=>$item):$pid=$item['product_id']??(int)$k;if(!isset($products[$pid]))continue;$p=$products[$pid];?><div class="cart-row"><img src="<?=e(product_image($p))?>" alt="<?=e($p['name'])?>"><div class="row-info"><strong><?=e($p['name'])?></strong><p><?php if(!empty($item['color'])): ?><span style="display:inline-block; margin-left:10px;">اللون: <b><?=e($item['color'])?></b></span><?php endif; ?><?php if(!empty($item['size'])): ?><span>المقاس: <b><?=e($item['size'])?></b></span><?php endif; ?></p><form method="post" action="<?=base('api/orders.php?action=update-cart')?>"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="cart_key" value="<?=e($k)?>"><input type="number" name="qty" value="<?=$item['qty']?>" min="0"><button class="link">تحديث</button></form></div><strong><?=money($p['price']*$item['qty'])?></strong></div><?php endforeach;?></div><aside class="summary"><h3>ملخص الطلب</h3><div><span>المجموع الفرعي</span><span><?=money($subtotal)?></span></div><div><span>الشحن</span><span>يُحسب عند العنوان</span></div><div class="total"><span>الإجمالي</span><span><?=money($subtotal)?></span></div><a class="btn" href="<?=base('checkout.php')?>">إتمام الطلب</a></aside></div><?php endif;?></div><?php include __DIR__.'/includes/footer.php';?>
